enum ServiceRegistry {
    private static let lock = NSLock()
    nonisolated(unsafe) private static var services: [String: Any] = [:]
    static func register(_ name: String, _ service: Any) {
        lock.lock(); defer { lock.unlock() }
        precondition(services[name] == nil, "duplicate service")
        services[name] = service
    }
    static func lookup<T>(_ name: String) throws -> T {
        lock.lock(); defer { lock.unlock() }
        guard let service = services[name] as? T else { throw RegistryError.unknown(name) }
        return service
    }
}

