actor ServiceRegistry {
    private var services: [String: any Service] = [:]
    func register(_ name: String, _ service: any Service) throws {
        guard services[name] == nil else { throw RegistryError.duplicate(name) }
        services[name] = service
    }
    func lookup(_ name: String) throws -> any Service {
        guard let service = services[name] else { throw RegistryError.unknown(name) }
        return service
    }
}
